<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import PageHeader from '@/Components/layout/PageHeader.vue'; import AppSnackbar from '@/Components/common/AppSnackbar.vue'; import UserImportPanel from '@/Components/users/UserImportPanel.vue'; import { useAdministratorStore } from '@/stores/administrator.store'
const router = useRouter(); const store = useAdministratorStore(); const snackbar = ref(false); const message = ref(''); function importUsers(count: number) { store.importUsers(count); message.value = `${count} utilisateurs ont été importés.`; snackbar.value = true; window.setTimeout(() => void router.push({ name: 'admin-users' }), 700) }
</script>
<template><div class="mx-auto w-full max-w-[1250px]"><PageHeader><template #title>Importer des utilisateurs</template><template #description>Ajoutez plusieurs collaborateurs à partir d’un fichier structuré.</template><template #actions><v-btn variant="text" prepend-icon="mdi-arrow-left" :to="{ name: 'admin-users' }">Retour aux utilisateurs</v-btn></template></PageHeader><UserImportPanel @import="importUsers" /><AppSnackbar v-model="snackbar" :message="message" /></div></template>
